@Mod.EventBusSubscriber(modid=KaleidoscopeGrilling.MOD_ID,value=Dist.CLIENT)public final class OilPotHud{@SubscribeEvent public static void render(RenderGuiOverlayEvent.Post e){Minecraft m=Minecraft.getInstance();if(m.level==null||m.options.hideGui||!(m.hitResult instanceof BlockHitResult h)||!(m.level.getBlockEntity(h.getBlockPos())instanceof TypedOilPotAccess oil))return;String type=oil.grilling$getOilType();int count=oil.grilling$getOilCount();Component line=Component.translatable("tooltip.kaleidoscope_grilling.oil_pot."+(type.isEmpty()?(count>0?"fat":"empty"):type),count);GuiGraphics g=e.getGuiGraphics();int w=m.font.width(line)+20,x=(m.getWindow().getGuiScaledWidth()-w)/2,y=m.getWindow().getGuiScaledHeight()/2+26;g.fill(x,y,x+w,y+20,0xD8121718);g.fill(x,y,x+3,y+20,0xFFE0A83B);g.drawString(m.font,line,x+10,y+6,0xFFF3E9D2,false);}private OilPotHud(){}}
